DECLARE
    v_email TEXT;
BEGIN
    SELECT email INTO v_email FROM users WHERE registerNumber = p_reg LIMIT 1;
    RETURN v_email;
END;

DECLARE
  cmd record;
BEGIN
  FOR cmd IN
    SELECT *
    FROM pg_event_trigger_ddl_commands()
    WHERE command_tag IN ('CREATE TABLE', 'CREATE TABLE AS', 'SELECT INTO')
      AND object_type IN ('table','partitioned table')
  LOOP
     IF cmd.schema_name IS NOT NULL AND cmd.schema_name IN ('public') AND cmd.schema_name NOT IN ('pg_catalog','information_schema') AND cmd.schema_name NOT LIKE 'pg_toast%' AND cmd.schema_name NOT LIKE 'pg_temp%' THEN
      BEGIN
        EXECUTE format('alter table if exists %s enable row level security', cmd.object_identity);
        RAISE LOG 'rls_auto_enable: enabled RLS on %', cmd.object_identity;
      EXCEPTION
        WHEN OTHERS THEN
          RAISE LOG 'rls_auto_enable: failed to enable RLS on %', cmd.object_identity;
      END;
     ELSE
        RAISE LOG 'rls_auto_enable: skip % (either system schema or not in enforced list: %.)', cmd.object_identity, cmd.schema_name;
     END IF;
  END LOOP;
END;

DECLARE
    v_user_id UUID;
    v_order_id UUID;
    v_subtotal DOUBLE PRECISION := 0;
    v_total DOUBLE PRECISION := 0;
    v_item RECORD;
    v_product RECORD;
    v_existing_order UUID;

    v_today DATE;
    v_next_token INTEGER;
    v_token_string VARCHAR(50);
    v_settings RECORD;
BEGIN
    -- 1. Identify the authenticated user
    v_user_id := auth.uid();
    IF v_user_id IS NULL THEN
        RAISE EXCEPTION 'Unauthorized: User must be logged in to place an order.';
    END IF;

    -- 1.5. Check Emergency Shutdown and Booking Status
    SELECT * INTO v_settings FROM public.settings LIMIT 1;
    IF FOUND THEN
        IF v_settings.is_emergency_closed = true THEN
            RAISE EXCEPTION 'Cafeteria ordering is temporarily closed.';
        END IF;
        IF v_settings.is_booking_enabled = false THEN
            RAISE EXCEPTION 'Ordering is currently closed.';
        END IF;
    END IF;

    -- 2. Fast-path Idempotency Check
    SELECT id INTO v_existing_order FROM orders WHERE idempotency_key = p_idempotency_key;
    IF v_existing_order IS NOT NULL THEN
        RETURN jsonb_build_object(
            'status', 'success',
            'message', 'Order already processed',
            'order_id', v_existing_order
        );
    END IF;

    -- 3. Calculate Subtotal Server-Side by looping through cart items
    FOR v_item IN SELECT * FROM jsonb_to_recordset(p_cart_items) AS x(product_id UUID, quantity INT)
    LOOP
        SELECT * INTO v_product FROM products WHERE id = v_item.product_id;

        IF NOT FOUND THEN
            RAISE EXCEPTION 'Product with ID % does not exist.', v_item.product_id;
        END IF;

        IF v_product.availability != 'AVAILABLE' THEN
            RAISE EXCEPTION 'Product % is currently unavailable.', v_product.name;
        END IF;

        IF v_item.quantity <= 0 THEN
            RAISE EXCEPTION 'Invalid quantity for product %.', v_product.name;
        END IF;

        v_subtotal := v_subtotal + (v_product.price * v_item.quantity);
    END LOOP;

    v_total := v_subtotal;

    -- 4. Generate Daily Token (Concurrency Safe & Asia/Kolkata Timezone)
    v_today := (CURRENT_TIMESTAMP AT TIME ZONE 'Asia/Kolkata')::DATE;

    INSERT INTO public.daily_token_counter (date_key, last_token)
    VALUES (v_today, 1)
    ON CONFLICT (date_key) 
    DO UPDATE SET last_token = daily_token_counter.last_token + 1
    RETURNING last_token INTO v_next_token;

    -- Format token, e.g., 'A041'
    v_token_string := 'A' || LPAD(v_next_token::TEXT, 3, '0');

    -- 5. Insert the Order inside an Exception Block for Race Conditions
    BEGIN
        INSERT INTO orders (
            user_id,
            subtotal,
            total,
            order_status,
            payment_status,
            payment_method,
            idempotency_key,
            token_number
        ) VALUES (
            v_user_id,
            v_subtotal,
            v_total,
            'PLACED',
            'PENDING',
            'ONLINE',
            p_idempotency_key,
            v_token_string
        ) RETURNING id INTO v_order_id;
    EXCEPTION WHEN unique_violation THEN
        SELECT id INTO v_existing_order FROM orders WHERE idempotency_key = p_idempotency_key;
        RETURN jsonb_build_object(
            'status', 'success',
            'message', 'Order already processed (concurrent)',
            'order_id', v_existing_order
        );
    END;

    -- 6. Insert all Order Items
    FOR v_item IN SELECT * FROM jsonb_to_recordset(p_cart_items) AS x(product_id UUID, quantity INT)
    LOOP
        SELECT * INTO v_product FROM products WHERE id = v_item.product_id;

        INSERT INTO order_items (
            order_id,
            product_id,
            quantity,
            product_name,
            product_price
        ) VALUES (
            v_order_id,
            v_item.product_id,
            v_item.quantity,
            v_product.name,
            v_product.price
        );
    END LOOP;

    -- 7. Return success
    RETURN jsonb_build_object(
        'status', 'success',
        'order_id', v_order_id,
        'total', v_total
    );

EXCEPTION
    WHEN OTHERS THEN
        RAISE EXCEPTION 'Checkout failed: %', SQLERRM;
END;

DECLARE
    v_calling_role TEXT;
    v_is_admin BOOLEAN := false;
BEGIN
    -- 1. Identify the current execution context role
    -- PostgREST explicitly sets 'role' to 'authenticated', 'anon', or 'service_role'.
    -- Direct Postgres DB connections will return their login role (e.g., 'postgres').
    v_calling_role := current_setting('role', true);

    -- 2. Trusted internal superusers and service backends strictly bypass this protection
    IF v_calling_role IN ('service_role', 'postgres', 'supabase_admin') THEN
        RETURN NEW;
    END IF;

    -- 3. If an authenticated REST user is making the request, verify if they are genuinely an ADMIN
    IF v_calling_role = 'authenticated' AND auth.uid() IS NOT NULL THEN
        SELECT EXISTS (
            SELECT 1 FROM public.users 
            WHERE id = auth.uid() AND role = 'ADMIN'
        ) INTO v_is_admin;
    END IF;

    -- 4. If NOT an Admin, explicitly reject attempts to escalate or tamper with protected fields
    IF NOT v_is_admin THEN
        IF NEW.role IS DISTINCT FROM OLD.role THEN
            RAISE EXCEPTION 'Unauthorized modification of protected user field: role';
        END IF;

        IF NEW.id IS DISTINCT FROM OLD.id THEN
            RAISE EXCEPTION 'Unauthorized modification of protected user field: id';
        END IF;

        IF NEW.created_at IS DISTINCT FROM OLD.created_at THEN
            RAISE EXCEPTION 'Unauthorized modification of protected user field: created_at';
        END IF;
    END IF;

    RETURN NEW;
END;

BEGIN
    -- Verify the new Auth user exists
    IF NOT EXISTS (
        SELECT 1
        FROM auth.users
        WHERE id = p_new_id
          AND lower(email) = lower(p_email)
    ) THEN
        RAISE EXCEPTION 'Target Auth user does not exist or email does not match';
    END IF;

    -- Verify the target public.users ID is unused
    IF EXISTS (
        SELECT 1
        FROM public.users
        WHERE id = p_new_id
    ) THEN
        RAISE EXCEPTION 'Target public.users UUID is already in use';
    END IF;

    -- Verify the old profile exists and email matches
    IF NOT EXISTS (
        SELECT 1
        FROM public.users
        WHERE id = p_old_id
          AND lower(email) = lower(p_email)
    ) THEN
        RAISE EXCEPTION 'Source public.users profile does not exist or email does not match';
    END IF;

    -- Make the UUID migration
    UPDATE public.users
    SET id = p_new_id
    WHERE id = p_old_id
      AND lower(email) = lower(p_email);

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Profile migration failed';
    END IF;
END;

